import { beforeEach } from 'vitest';
import type { EditorFactory } from '../src/lib/editor';

/** A fake editor factory backed by a plain `<textarea aria-label="Source">`, so
 *  integration tests can drive the editing surface without CodeMirror (which is
 *  covered directly in `editor.test.ts` and exercised by the Playwright e2e). */
export function fakeEditorFactory(): EditorFactory {
  return ({ parent, doc, onChange, onscroll }) => {
    const area = document.createElement('textarea');
    area.setAttribute('aria-label', 'Source');
    area.value = doc;
    area.addEventListener('input', () => onChange(area.value));
    parent.appendChild(area);
    if (onscroll !== undefined) onscroll(0);
    return {
      setDoc(value) {
        if (value !== area.value) {
          area.value = value;
        }
      },
      setDiagnostics() {},
      gotoLine() {},
      currentLine() {
        return 1;
      },
      setKeymapMode() {},
      setSpellChecker() {},
      setViewMode() {},
      toggleBold() {},
      toggleItalic() {},
      promoteHeading() {},
      demoteHeading() {},
      insertAtCursor(text) {
        area.value += text;
        onChange(area.value);
      },
      destroy() {
        area.remove();
      }
    };
  };
}

/** Dispatch a pointer event carrying `clientX` (jsdom drops it from
 *  `fireEvent`'s synthetic pointer events). */
export function firePointer(type: string, target: EventTarget, clientX: number): void {
  const event = new Event(type, { bubbles: true });
  Object.defineProperty(event, 'clientX', { value: clientX });
  target.dispatchEvent(event);
}

/** Dispatch a pointer event carrying `clientY` (for horizontal resize handles). */
export function firePointerY(type: string, target: EventTarget, clientY: number): void {
  const event = new Event(type, { bubbles: true });
  Object.defineProperty(event, 'clientY', { value: clientY });
  target.dispatchEvent(event);
}

/** A minimal `matchMedia` stub (jsdom ships none). Tests override `matches`
 *  by reassigning `window.matchMedia` where they need dark / reduced-motion. */
export function stubMatchMedia(matches = false): typeof window.matchMedia {
  return ((query: string) => ({
    matches,
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false
  })) as unknown as typeof window.matchMedia;
}

beforeEach(() => {
  window.localStorage.clear();
  window.matchMedia = stubMatchMedia(false);
  document.documentElement.removeAttribute('data-theme');
});

import { test } from '@playwright/test';
import { execFileSync } from 'node:child_process';
import { mkdirSync } from 'node:fs';

// Renders docs/assets/install.png from the REAL install-script output (demo mode),
// so the terminal screenshot in the README never drifts from the installer. Run
// via `just install-shot`.
const OUT = '../../docs/assets';
mkdirSync(OUT, { recursive: true });

/** Convert the installer's truecolor ANSI (only `38;2;r;g;b` + reset) to HTML. */
function ansiToHtml(input: string): string {
  const esc = (t: string) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  // ESC built from a char code so the source has no control-character literal.
  const re = new RegExp(String.fromCharCode(27) + '\\[(0|38;2;\\d+;\\d+;\\d+)m', 'g');
  let html = '';
  let last = 0;
  let open = false;
  let m: RegExpExecArray | null;
  while ((m = re.exec(input)) !== null) {
    html += esc(input.slice(last, m.index));
    last = re.lastIndex;
    if (open) {
      html += '</span>';
      open = false;
    }
    if (m[1] !== '0') {
      const parts = m[1].split(';');
      html += `<span style="color:rgb(${parts[2]},${parts[3]},${parts[4]})">`;
      open = true;
    }
  }
  html += esc(input.slice(last));
  if (open) html += '</span>';
  return html;
}

test('installer terminal screenshot', async ({ page }) => {
  const ansi = execFileSync('sh', ['../../scripts/install/install.sh'], {
    encoding: 'utf8',
    env: { ...process.env, GALLEY_INSTALL_DEMO: '1', GALLEY_VERSION: '0.9.2' }
  });

  const body = ansiToHtml(ansi);
  await page.setContent(`<!doctype html><html><body style="margin:0;background:#0d0c0a">
    <div class="term" style="display:inline-block;background:#141210;color:#ece3d0;
         padding:22px 26px;border-radius:10px;font-family:'DejaVu Sans Mono','Cascadia Mono',monospace;
         font-size:15px;line-height:1.32;white-space:pre">
      <div style="color:#9a8e7e;margin-bottom:10px">$ curl -fsSL https://github.com/achref-soua/galley/releases/latest/download/install.sh | sh</div>${body}</div>
  </body></html>`);

  await page.locator('.term').screenshot({ path: `${OUT}/install.png` });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

const invoke = vi.fn();
vi.mock('@tauri-apps/api/core', () => ({ invoke: (...args: unknown[]) => invoke(...args) }));

import {
  browserAgentToolBackend,
  tauriAgentToolBackend,
  selectAgentToolBackend,
  dispatchTool,
  type AgentToolBackend
} from '../src/lib/agent-backend';

beforeEach(() => {
  invoke.mockReset();
});

// ── tauriAgentToolBackend ─────────────────────────────────────────────────────

describe('tauriAgentToolBackend — success paths', () => {
  const root = '/projects/p';

  it('readFile calls read_document and returns ok', async () => {
    invoke.mockResolvedValueOnce('file content');
    const r = await tauriAgentToolBackend(root).readFile('main.tex');
    expect(invoke).toHaveBeenCalledWith('read_document', { projectRoot: root, path: 'main.tex' });
    expect(r).toEqual({ ok: true, output: 'file content' });
  });

  it('searchProject calls search_project and joins results', async () => {
    invoke.mockResolvedValueOnce(['main.tex:1', 'intro.tex:5']);
    const r = await tauriAgentToolBackend(root).searchProject('section');
    expect(invoke).toHaveBeenCalledWith('search_project', { projectRoot: root, query: 'section' });
    expect(r).toEqual({ ok: true, output: 'main.tex:1\nintro.tex:5' });
  });

  it('compile calls compile_document and returns ok', async () => {
    invoke.mockResolvedValueOnce('Compilation log');
    const r = await tauriAgentToolBackend(root).compile();
    expect(invoke).toHaveBeenCalledWith('compile_document', { projectRoot: root });
    expect(r).toEqual({ ok: true, output: 'Compilation log' });
  });

  it('readDiagnostics calls read_diagnostics and returns ok', async () => {
    invoke.mockResolvedValueOnce('! Undefined');
    const r = await tauriAgentToolBackend(root).readDiagnostics();
    expect(invoke).toHaveBeenCalledWith('read_diagnostics', { projectRoot: root });
    expect(r).toEqual({ ok: true, output: '! Undefined' });
  });

  it('lookupReference calls lookup_reference and returns ok', async () => {
    invoke.mockResolvedValueOnce('Author 2024');
    const r = await tauriAgentToolBackend(root).lookupReference('deep learning');
    expect(invoke).toHaveBeenCalledWith('lookup_reference', {
      projectRoot: root,
      query: 'deep learning'
    });
    expect(r).toEqual({ ok: true, output: 'Author 2024' });
  });

  it('applyPatch returns the patch directly without invoking Tauri', async () => {
    const r = await tauriAgentToolBackend(root).applyPatch('\\textbf{fixed}');
    expect(invoke).not.toHaveBeenCalled();
    expect(r).toEqual({ ok: true, output: '\\textbf{fixed}' });
  });

  it('listAssets calls list_assets and joins results', async () => {
    invoke.mockResolvedValueOnce(['fig1.pdf', 'fig2.png']);
    const r = await tauriAgentToolBackend(root).listAssets();
    expect(invoke).toHaveBeenCalledWith('list_assets', { projectRoot: root });
    expect(r).toEqual({ ok: true, output: 'fig1.pdf\nfig2.png' });
  });
});

describe('tauriAgentToolBackend — error paths', () => {
  const root = '/projects/p';

  it('readFile returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('not found'));
    const r = await tauriAgentToolBackend(root).readFile('missing.tex');
    expect(r.ok).toBe(false);
    expect(r.output).toContain('not found');
  });

  it('searchProject returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('search failed'));
    const r = await tauriAgentToolBackend(root).searchProject('x');
    expect(r.ok).toBe(false);
  });

  it('compile returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('compile error'));
    const r = await tauriAgentToolBackend(root).compile();
    expect(r.ok).toBe(false);
  });

  it('readDiagnostics returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('diag error'));
    const r = await tauriAgentToolBackend(root).readDiagnostics();
    expect(r.ok).toBe(false);
  });

  it('lookupReference returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('lookup failed'));
    const r = await tauriAgentToolBackend(root).lookupReference('x');
    expect(r.ok).toBe(false);
  });

  it('listAssets returns ok: false on invoke failure', async () => {
    invoke.mockRejectedValueOnce(new Error('assets error'));
    const r = await tauriAgentToolBackend(root).listAssets();
    expect(r.ok).toBe(false);
  });
});

// ── browserAgentToolBackend ───────────────────────────────────────────────────

describe('browserAgentToolBackend', () => {
  it('readFile returns ok with stub output', async () => {
    const r = await browserAgentToolBackend().readFile('main.tex');
    expect(r.ok).toBe(true);
    expect(r.output.length).toBeGreaterThan(0);
  });

  it('searchProject returns ok with stub output mentioning the query', async () => {
    const r = await browserAgentToolBackend().searchProject('intro');
    expect(r.ok).toBe(true);
    expect(r.output).toContain('intro');
  });

  it('compile returns ok', async () => {
    const r = await browserAgentToolBackend().compile();
    expect(r.ok).toBe(true);
  });

  it('readDiagnostics returns ok', async () => {
    const r = await browserAgentToolBackend().readDiagnostics();
    expect(r.ok).toBe(true);
  });

  it('lookupReference returns ok with stub output mentioning the query', async () => {
    const r = await browserAgentToolBackend().lookupReference('deep learning');
    expect(r.ok).toBe(true);
    expect(r.output).toContain('deep learning');
  });

  it('applyPatch returns the patch text', async () => {
    const r = await browserAgentToolBackend().applyPatch('\\section{New}');
    expect(r.ok).toBe(true);
    expect(r.output).toBe('\\section{New}');
  });

  it('listAssets returns ok', async () => {
    const r = await browserAgentToolBackend().listAssets();
    expect(r.ok).toBe(true);
  });
});

// ── dispatchTool ──────────────────────────────────────────────────────────────

describe('dispatchTool', () => {
  function makeBackend(result: { ok: boolean; output: string }): AgentToolBackend {
    return {
      readFile: vi.fn().mockResolvedValue(result),
      searchProject: vi.fn().mockResolvedValue(result),
      compile: vi.fn().mockResolvedValue(result),
      readDiagnostics: vi.fn().mockResolvedValue(result),
      lookupReference: vi.fn().mockResolvedValue(result),
      applyPatch: vi.fn().mockResolvedValue(result),
      listAssets: vi.fn().mockResolvedValue(result)
    };
  }

  const ok = { ok: true, output: 'ok' };

  it('routes read_file to backend.readFile', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'read_file', 'main.tex');
    expect(b.readFile).toHaveBeenCalledWith('main.tex');
  });

  it('routes search_project to backend.searchProject', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'search_project', 'query');
    expect(b.searchProject).toHaveBeenCalledWith('query');
  });

  it('routes compile to backend.compile', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'compile', '');
    expect(b.compile).toHaveBeenCalled();
  });

  it('routes read_diagnostics to backend.readDiagnostics', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'read_diagnostics', '');
    expect(b.readDiagnostics).toHaveBeenCalled();
  });

  it('routes lookup_reference to backend.lookupReference', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'lookup_reference', 'deep learning');
    expect(b.lookupReference).toHaveBeenCalledWith('deep learning');
  });

  it('routes apply_patch to backend.applyPatch', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'apply_patch', '\\section{New}');
    expect(b.applyPatch).toHaveBeenCalledWith('\\section{New}');
  });

  it('routes list_assets to backend.listAssets', async () => {
    const b = makeBackend(ok);
    await dispatchTool(b, 'list_assets', '');
    expect(b.listAssets).toHaveBeenCalled();
  });

  it('returns ok: false for an unrecognised tool name', async () => {
    const b = makeBackend(ok);
    const r = await dispatchTool(b, 'teleport', 'mars');
    expect(r.ok).toBe(false);
    expect(r.output).toContain('teleport');
  });
});

// ── selectAgentToolBackend ────────────────────────────────────────────────────

describe('selectAgentToolBackend', () => {
  it('returns a browserAgentToolBackend when __TAURI_INTERNALS__ is absent', () => {
    const b = selectAgentToolBackend('/p', {} as Window);
    expect(typeof b.readFile).toBe('function');
    expect(typeof b.compile).toBe('function');
  });

  it('returns a tauriAgentToolBackend when __TAURI_INTERNALS__ is present', () => {
    const win = { __TAURI_INTERNALS__: {} } as unknown as Window;
    const b = selectAgentToolBackend('/p', win);
    expect(typeof b.readFile).toBe('function');
    expect(typeof b.compile).toBe('function');
  });
});

import { describe, it, expect } from 'vitest';
import {
  buildRegex,
  escapeRegex,
  searchInContent,
  replaceInContent
} from '../src/lib/search-content';

const baseQuery = { pattern: '', caseSensitive: false, wholeWord: false, useRegex: false };

describe('escapeRegex', () => {
  it('escapes regex special characters', () => {
    const special = '.*+?^${}()|[]\\';
    const escaped = escapeRegex(special);
    expect(() => new RegExp(escaped)).not.toThrow();
    expect(new RegExp(escaped).test(special)).toBe(true);
  });

  it('leaves plain strings unchanged in effect', () => {
    expect(escapeRegex('hello')).toBe('hello');
  });
});

describe('buildRegex', () => {
  it('returns null for empty pattern', () => {
    expect(buildRegex({ ...baseQuery, pattern: '' })).toBeNull();
  });

  it('returns null for invalid regex when useRegex is true', () => {
    expect(buildRegex({ ...baseQuery, pattern: '[invalid', useRegex: true })).toBeNull();
  });

  it('builds a case-insensitive regex by default', () => {
    const re = buildRegex({ ...baseQuery, pattern: 'Hello' });
    expect(re).not.toBeNull();
    expect(re!.flags).toContain('i');
  });

  it('builds a case-sensitive regex when caseSensitive is true', () => {
    const re = buildRegex({ ...baseQuery, pattern: 'Hello', caseSensitive: true });
    expect(re!.flags).not.toContain('i');
  });

  it('wraps pattern with \\b…\\b when wholeWord is true', () => {
    const re = buildRegex({ ...baseQuery, pattern: 'foo', wholeWord: true });
    expect(re!.source).toContain('\\b');
  });

  it('escapes the pattern when useRegex is false', () => {
    const re = buildRegex({ ...baseQuery, pattern: '1+1' });
    expect(re!.test('1+1')).toBe(true);
    expect(re!.test('111')).toBe(false);
  });

  it('uses the raw pattern as regex when useRegex is true', () => {
    const re = buildRegex({ ...baseQuery, pattern: '\\d+', useRegex: true });
    expect(re!.test('123')).toBe(true);
  });
});

describe('searchInContent', () => {
  it('returns empty for empty pattern', () => {
    expect(searchInContent('hello', { ...baseQuery, pattern: '' })).toHaveLength(0);
  });

  it('returns empty when no match is found', () => {
    expect(searchInContent('hello', { ...baseQuery, pattern: 'xyz' })).toHaveLength(0);
  });

  it('finds a single match and reports correct line/column', () => {
    const results = searchInContent('hello world', { ...baseQuery, pattern: 'world' });
    expect(results).toHaveLength(1);
    expect(results[0].line).toBe(1);
    expect(results[0].column).toBe(7);
    expect(results[0].lineText).toBe('hello world');
    expect(results[0].matchStart).toBe(6);
    expect(results[0].matchEnd).toBe(11);
  });

  it('finds matches on multiple lines', () => {
    const results = searchInContent('foo\nfoo\nbar', { ...baseQuery, pattern: 'foo' });
    expect(results).toHaveLength(2);
    expect(results[0].line).toBe(1);
    expect(results[1].line).toBe(2);
  });

  it('is case-insensitive by default', () => {
    const results = searchInContent('Hello', { ...baseQuery, pattern: 'hello' });
    expect(results).toHaveLength(1);
  });

  it('respects caseSensitive: true', () => {
    expect(
      searchInContent('Hello', { ...baseQuery, pattern: 'hello', caseSensitive: true })
    ).toHaveLength(0);
    expect(
      searchInContent('hello', { ...baseQuery, pattern: 'hello', caseSensitive: true })
    ).toHaveLength(1);
  });

  it('respects wholeWord matching', () => {
    expect(
      searchInContent('foobar foo', { ...baseQuery, pattern: 'foo', wholeWord: true })
    ).toHaveLength(1);
  });

  it('handles CRLF line endings', () => {
    const results = searchInContent('line1\r\nline2', { ...baseQuery, pattern: 'line2' });
    expect(results).toHaveLength(1);
    expect(results[0].line).toBe(2);
  });

  it('returns empty for an invalid regex pattern', () => {
    expect(searchInContent('text', { ...baseQuery, pattern: '[bad', useRegex: true })).toHaveLength(
      0
    );
  });

  it('finds multiple matches on the same line', () => {
    const results = searchInContent('aa aa aa', { ...baseQuery, pattern: 'aa' });
    expect(results).toHaveLength(3);
  });

  it('handles zero-length regex matches without looping forever', () => {
    // a* can match zero-length strings between characters — the guard advances lastIndex.
    const results = searchInContent('ab', { ...baseQuery, pattern: 'x*', useRegex: true });
    // x* matches zero-length at every position; we just verify it completes and returns results.
    expect(Array.isArray(results)).toBe(true);
  });
});

describe('replaceInContent', () => {
  it('returns original content when pattern is empty', () => {
    const content = 'hello';
    expect(replaceInContent(content, { ...baseQuery, pattern: '' }, 'x')).toBe(content);
  });

  it('returns original content for invalid regex', () => {
    const content = 'hello';
    expect(replaceInContent(content, { ...baseQuery, pattern: '[bad', useRegex: true }, 'x')).toBe(
      content
    );
  });

  it('replaces all occurrences of a literal pattern', () => {
    expect(replaceInContent('foo foo foo', { ...baseQuery, pattern: 'foo' }, 'bar')).toBe(
      'bar bar bar'
    );
  });

  it('replaces using regex back-references when useRegex is true', () => {
    const result = replaceInContent(
      'hello world',
      { ...baseQuery, pattern: '(\\w+)', useRegex: true },
      '[$1]'
    );
    expect(result).toBe('[hello] [world]');
  });
});

import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/svelte';
import SearchPanel from '../src/lib/SearchPanel.svelte';
import { browserProjectBackend, type ProjectBackend } from '../src/lib/project-backend';

const ROOT = '/project';

/** Build a backend that has 'main.tex' with the given content, pre-seeded. */
async function seedBackend(content: string) {
  const b = browserProjectBackend();
  // Use the public API: create a project, then save a document.
  await b.createProject('/parent', 'test');
  await b.saveDocument(ROOT, 'main.tex', content);
  return b;
}

const baseProps = (overrides: object = {}) => ({
  root: ROOT,
  backend: browserProjectBackend(),
  activeContent: '',
  activePath: null,
  onclose: vi.fn(),
  onreplace: vi.fn(),
  ...overrides
});

describe('SearchPanel', () => {
  it('renders the search UI with pattern input, options, and replace controls', () => {
    render(SearchPanel, { props: baseProps() });
    expect(screen.getByLabelText('Search pattern')).toBeTruthy();
    expect(screen.getByLabelText('Replacement text')).toBeTruthy();
    expect(screen.getByText('Search')).toBeTruthy();
    expect(screen.getByText('Replace all')).toBeTruthy();
  });

  it('closes on Escape key', async () => {
    const onclose = vi.fn();
    render(SearchPanel, { props: baseProps({ onclose }) });
    await fireEvent.keyDown(screen.getByLabelText('Search pattern'), { key: 'Escape' });
    expect(onclose).toHaveBeenCalledOnce();
  });

  it('closes via the ✕ button', async () => {
    const onclose = vi.fn();
    render(SearchPanel, { props: baseProps({ onclose }) });
    await fireEvent.click(screen.getByLabelText('Close search'));
    expect(onclose).toHaveBeenCalledOnce();
  });

  it('shows no results message after searching with no matches', async () => {
    render(SearchPanel, { props: baseProps({ activeContent: 'hello world' }) });
    const input = screen.getByLabelText('Search pattern');
    await fireEvent.input(input, { target: { value: 'zzz' } });
    await fireEvent.click(screen.getByText('Search'));
    expect(screen.getByText('No matches.')).toBeTruthy();
  });

  it('does nothing on search with empty pattern', async () => {
    render(SearchPanel, { props: baseProps() });
    await fireEvent.click(screen.getByText('Search'));
    expect(screen.queryByText('No matches.')).toBeNull();
  });

  it('shows no-matches when root is null (no project open)', async () => {
    render(SearchPanel, { props: baseProps({ root: null }) });
    const input = screen.getByLabelText('Search pattern');
    await fireEvent.input(input, { target: { value: 'foo' } });
    await fireEvent.click(screen.getByText('Search'));
    // With no project root, results stay empty → "No matches." is shown.
    expect(screen.getByText('No matches.')).toBeTruthy();
  });

  it('fires search on Enter key in the pattern input', async () => {
    render(SearchPanel, { props: baseProps({ activeContent: 'hello' }) });
    const input = screen.getByLabelText('Search pattern');
    await fireEvent.input(input, { target: { value: 'nope' } });
    await fireEvent.keyDown(input, { key: 'Enter' });
    expect(screen.getByText('No matches.')).toBeTruthy();
  });

  it('toggles the case-sensitive option', async () => {
    const { container } = render(SearchPanel, { props: baseProps() });
    const checkbox = container.querySelector('input[type="checkbox"]') as HTMLInputElement;
    expect(checkbox.checked).toBe(false);
    await fireEvent.click(checkbox);
    expect(checkbox.checked).toBe(true);
  });

  it('does not replace-all when pattern is empty', async () => {
    const onreplace = vi.fn();
    render(SearchPanel, { props: baseProps({ onreplace }) });
    await fireEvent.click(screen.getByText('Replace all'));
    expect(onreplace).not.toHaveBeenCalled();
  });

  it('does not replace-all when root is null', async () => {
    const onreplace = vi.fn();
    render(SearchPanel, { props: baseProps({ root: null, onreplace }) });
    const input = screen.getByLabelText('Search pattern');
    await fireEvent.input(input, { target: { value: 'foo' } });
    await fireEvent.click(screen.getByText('Replace all'));
    expect(onreplace).not.toHaveBeenCalled();
  });

  it('calls onreplace when replacing in the active file', async () => {
    const onreplace = vi.fn();
    const backend = await seedBackend('hello world');
    render(SearchPanel, {
      props: baseProps({
        backend,
        activeContent: 'hello world',
        activePath: 'main.tex',
        onreplace
      })
    });
    const patternInput = screen.getByLabelText('Search pattern');
    await fireEvent.input(patternInput, { target: { value: 'hello' } });
    await fireEvent.click(screen.getByText('Search'));
    const replInput = screen.getByLabelText('Replacement text');
    await fireEvent.input(replInput, { target: { value: 'goodbye' } });
    await fireEvent.click(screen.getByText('Replace all'));
    expect(onreplace).toHaveBeenCalledWith('main.tex', 'goodbye world');
  });

  it('shows an error message when searchProject throws an Error', async () => {
    const backend: ProjectBackend = {
      ...browserProjectBackend(),
      searchProject: async () => {
        throw new Error('network error');
      }
    };
    render(SearchPanel, { props: baseProps({ backend }) });
    await fireEvent.input(screen.getByLabelText('Search pattern'), { target: { value: 'foo' } });
    await fireEvent.click(screen.getByText('Search'));
